            "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" font-size=\"36\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">The World of Cleopatra VII</text><text x=\"550\" y=\"115\" font-size=\"24\" fill=\"#9ca3af\" text-anchor=\"middle\">Last Pharaoh of Egypt, 69-30 BCE</text><rect x=\"80\" y=\"180\" width=\"940\" height=\"180\" fill=\"#16213e\" stroke=\"#6366f1\" stroke-width=\"2\" rx=\"10\"/><text x=\"550\" y=\"220\" font-size=\"26\" fill=\"#6366f1\" text-anchor=\"middle\" font-weight=\"bold\">Three Identities, One Queen</text><text x=\"550\" y=\"265\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Greek Macedonian by blood and language</text><text x=\"550\" y=\"300\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Pharaoh of Egypt by title and ritual</text><text x=\"550\" y=\"335\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Hellenistic monarch by political style</text><rect x=\"80\" y=\"400\" width=\"940\" height=\"240\" fill=\"#16213e\" stroke=\"#8b5cf6\" stroke-width=\"2\" rx=\"10\"/><text x=\"550\" y=\"440\" font-size=\"26\" fill=\"#8b5cf6\" text-anchor=\"middle\" font-weight=\"bold\">What Makes Her Story Extraordinary</text><text x=\"550\" y=\"485\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Allied with Julius Caesar, then Mark Antony</text><text x=\"550\" y=\"520\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Bore children to both Roman generals</text><text x=\"550\" y=\"555\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Lost the empire at the Battle of Actium</text><text x=\"550\" y=\"590\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Ended her life and her dynasty in August 30 BCE</text><rect x=\"80\" y=\"680\" width=\"940\" height=\"180\" fill=\"#16213e\" stroke=\"#10b981\" stroke-width=\"2\" rx=\"10\"/><text x=\"550\" y=\"720\" font-size=\"26\" fill=\"#10b981\" text-anchor=\"middle\" font-weight=\"bold\">Why She Still Matters</text><text x=\"550\" y=\"765\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Her death ended 3,000 years of pharaonic rule</text><text x=\"550\" y=\"800\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Her propaganda war shaped how Rome saw the East</text><text x=\"550\" y=\"835\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Her image has been remade in every age since</text><text x=\"550\" y=\"920\" font-size=\"22\" fill=\"#f59e0b\" text-anchor=\"middle\" font-style=\"italic\">\"I will not be triumphed over.\" - attributed to Cleopatra</text><text x=\"550\" y=\"960\" font-size=\"18\" fill=\"#9ca3af\" text-anchor=\"middle\">Six lessons on the woman behind the legend</text></svg>",
